--  Ejecutar como crd_owner:
--    psql -U crd_owner -d crd_rbac_poc -f db/04-seed.sql
-- ============================================================

BEGIN;

-- Usuarios sinteticos. Contrasena para todos: Demo2026!
ON CONFLICT (email) DO NOTHING;

-- Estudios
ON CONFLICT (codigo) DO NOTHING;

-- Sitios
ON CONFLICT (estudio_id, codigo) DO NOTHING;

-- Asignaciones: usuario + estudio + rol (estudio NULL = rol global)
ON CONFLICT DO NOTHING;

-- Pacientes (datos clinicos, sin identidad)
ON CONFLICT (estudio_id, codigo) DO NOTHING;

-- Identidad del paciente (tabla separada)
ON CONFLICT (paciente_id) DO NOTHING;

-- CRD
ON CONFLICT (paciente_id, tipo, visita) DO NOTHING;

-- Dosis: una fila por toma
ON CONFLICT (paciente_id, numero_toma) DO NOTHING;

-- Eventos adversos
ON CONFLICT (id) DO NOTHING;

