-- Resumen
SELECT 'usuarios' AS tabla, count(*) FROM usuario
UNION ALL SELECT 'estudios', count(*) FROM estudio
UNION ALL SELECT 'sitios', count(*) FROM sitio
UNION ALL SELECT 'asignaciones', count(*) FROM asignacion
UNION ALL SELECT 'pacientes', count(*) FROM paciente
UNION ALL SELECT 'identidades', count(*) FROM identidad_paciente
UNION ALL SELECT 'crd', count(*) FROM crd
UNION ALL SELECT 'dosis', count(*) FROM dosis
